            windows.append((start, idx, events[start][0], events[idx][0]))
            start=None
    print(f"paso2 windows: {[(a,b,la,lb) for (a,b,la,lb) in [(w[0],w[1],w[2],w[3]) for w in windows]]}")
    print(f"windows L ranges: {[(w[2], w[3]) for w in windows]}")

    # also corte / paso_omitido
