        if ev.get('tipo') in ('corte','paso_omitido','inicio'):
            print(f"  L{i} tipo={ev.get('tipo')} orden={ev.get('orden')} rol={ev.get('rol')} keys subset={ {k:ev.get(k) for k in ev if k in ('orden','rol','motivo','desde_paso','etapa','pasos')} }")

    for wi, (a,b,la,lb) in enumerate(windows):
        slice_ev=events[a:b+1]
        print(f"\n--- window {wi} L{la}-L{lb} n={len(slice_ev)} ---")
        writes=[]
