function parseLoginBody(body: unknown): { email: string; password: string } {
  if (!isRecord(body)) throw validationIssue("body", "Debe ser un objeto JSON");
  if (!("email" in body)) throw validationIssue("email", "Campo requerido");
  if (!("password" in body)) throw validationIssue("password", "Campo requerido");
  if (typeof body.email !== "string") throw validationIssue("email", "Debe ser string");
  if (typeof body.password !== "string") throw validationIssue("password", "Debe ser string");
