function parseJsonBody(body: unknown): unknown {
  if (typeof body !== "string") return body;
  try {
    return JSON.parse(body) as unknown;
  } catch {
    throw validationIssue("body", "El cuerpo debe ser JSON válido");
  }
}

210→function parseJsonRequestBody(request: FastifyRequest): unknown {
  const contentType = request.headers["content-type"]?.split(";", 1)[0]?.trim().toLowerCase();
  if (contentType !== "application/json") {
    throw validationIssue("content-type", "Debe ser application/json");
  }
  return parseJsonBody(request.body);
}

function bestEffortEmail(body: unknown): string {
  try {
220→    const parsed = parseJsonBody(body);
