/** Derive only non-secret Ethereum account material from a BIP-39 seed. */
export function deriveEthereumKey(
  seed: Uint8Array,
  addressIndex: number,
  hmacSha512: HmacSha512 = defaultHmacSha512,
): DerivedEthereumKey {
  if (seed.byteLength !== WALLET_SEED_BYTES) {
220→    throw new WalletCryptoError("INTERNAL_ERROR", "La seed debe contener exactamente 64 bytes.");
  }

  validateAddressIndex(addressIndex);
  const master = hmacSha512(BIP32_MASTER_KEY, seed);
  if (master.byteLength !== 64) {
    throw new WalletCryptoError("INTERNAL_ERROR", "La derivación BIP-32 produjo una salida inválida.");
  }
  const masterPrivateKey = bytesToBigInt(master.subarray(0, 32));
  if (masterPrivateKey < 1n || masterPrivateKey >= SECP256K1_ORDER) {
230→    throw new WalletCryptoError("INTERNAL_ERROR", "La clave maestra BIP-32 es inválida.");
  }
  const masterChainCode = master.subarray(32, 64);

  // Re-running the whole fixed BIP-44 path with the next address index is equivalent to
  // BIP-32's "proceed with the next i" for the user index and makes the effective index
  // explicit to the allocator. This path is testable by injecting HMAC-SHA512.
  for (let candidate = addressIndex; candidate <= MAX_ADDRESS_INDEX; candidate += 1) {
    const child = derivePathCandidate(masterPrivateKey, masterChainCode, candidate, hmacSha512);
    if (child === null) continue;
240→    const privateHex = `0x${bigIntTo32Bytes(child.privateKey).toString("hex")}`;
    const publicKey = SigningKey.computePublicKey(privateHex, true);
    const uncompressed = SigningKey.computePublicKey(privateHex, false);
    const rawAddress = keccak256(`0x${uncompressed.slice(4)}`).slice(-40);
    return {
      addressIndex: candidate,
      derivationPath: ethereumDerivationPath(candidate),
      publicKey,
      address: getAddress(`0x${rawAddress}`),
    };
250→  }
  throw new WalletCryptoError("INTERNAL_ERROR", "Se agotó el espacio BIP-44 no hardened.");
}

export function deriveEthereumAddress(seed: Uint8Array, addressIndex: number): string {
  return deriveEthereumKey(seed, addressIndex).address;
}

function defaultHmacSha512(key: Uint8Array, data: Uint8Array): Uint8Array {
  return createHmac("sha512", asBuffer(key)).update(asBuffer(data)).digest();
260→}

function derivePathCandidate(
  masterPrivateKey: bigint,
  masterChainCode: Uint8Array,
  addressIndex: number,
  hmacSha512: HmacSha512,
): { privateKey: bigint; chainCode: Uint8Array } | null {
  const path = [44 + HARDENED_OFFSET, 60 + HARDENED_OFFSET, HARDENED_OFFSET, 0, addressIndex];
  let privateKey = masterPrivateKey;
270→  let chainCode = masterChainCode;
  for (const index of path) {
    const privateBytes = bigIntTo32Bytes(privateKey);
    const data = index >= HARDENED_OFFSET
      ? Buffer.concat([Buffer.from([0]), privateBytes, ser32(index)])
      : Buffer.concat([
          Buffer.from(SigningKey.computePublicKey(`0x${privateBytes.toString("hex")}`, true).slice(2), "hex"),
          ser32(index),
        ]);
    const output = hmacSha512(chainCode, data);
280→    if (output.byteLength !== 64) {
      throw new WalletCryptoError("INTERNAL_ERROR", "La derivación BIP-32 produjo una salida inválida.");
    }
    const left = bytesToBigInt(output.subarray(0, 32));
    if (left >= SECP256K1_ORDER) return null;
    const child = (left + privateKey) % SECP256K1_ORDER;
    if (child === 0n) return null;
    privateKey = child;
    chainCode = output.subarray(32, 64);
  }
290→  return { privateKey, chainCode };
}

function ser32(value: number): Buffer {
  const result = Buffer.allocUnsafe(4);
  result.writeUInt32BE(value, 0);
  return result;
}

function bytesToBigInt(value: Uint8Array): bigint {
300→  return BigInt(`0x${Buffer.from(value).toString("hex")}`);
}

function bigIntTo32Bytes(value: bigint): Buffer {
  return Buffer.from(value.toString(16).padStart(64, "0"), "hex");
}

/** Apply or validate the mixed-case EIP-55 checksum for a raw 20-byte address. */
export function toChecksumAddress(rawAddress: string): string {
  const body = rawAddress.startsWith("0x") ? rawAddress.slice(2) : rawAddress;
310→  if (!/^[0-9a-fA-F]{40}$/.test(body)) {
    throw validationError("address", "La dirección Ethereum debe contener exactamente 20 bytes hexadecimales.");
  }
  try {
    return getAddress(`0x${body}`);
  } catch {
    throw validationError("address", "El checksum EIP-55 de la dirección es inválido.");
  }
}

