  token = null; clearing = null; clearRequested = false; ended = false; establishing = false;
  constructor(onCleared){ this.onCleared = onCleared; }
  currentToken(){ return this.token; }
  async establish(token){
    this.establishing = true;
    try {
      if (this.clearing !== null) await this.clearing;
      if (this.clearRequested) await this.clearSingleton();
      await store.saveToken(token);
      this.token = token;
      this.clearRequested = false;
      this.ended = false;
      this.clearing = null;
    } finally { this.establishing = false; }
  }
  clearSingleton(){
    if (this.clearing !== null) return this.clearing;
    if (!this.ended) {
      this.ended = true;
      this.token = null;
      this.clearRequested = true;
      this.onCleared();
